\label{1.1}  Let  $(R,\frak{m})$ be a  local ring and $M$ be a finitely generated $R$-module. For given integers $i$ and $t > 0$,  the following statements are equivalent:
\begin{enumerate}
\item [(1)] $\operatorname{Supp}_{\widehat{R}} (\mathfrak{F}^i_{\frak{a}}(M)) \subseteq V(\frak{m} \widehat{R})$ for all $i < t$;
\item[(2)] $\mathfrak{F}^i_{\frak{a}}(M)$ is Artinian for all $i < t$;
\item[(3)] $\operatorname{Supp}_{\widehat{R}} (\mathfrak{F}^i_{\frak{a}}(M)) \subseteq V(\frak{a} \widehat{R})$  for all $i < t$;
\item[(4)] $\frak{a} \subseteq \operatorname{Rad}(\operatorname{Ann}_R (\mathfrak{F}^i_{\frak{a}}(M)))$ for all $i < t$;

Suppose that   $t \leq \operatorname{depth} M$, then the above conditions are equivalent to
 \item[(5)] $\mathfrak{F}^i_{\frak{a}}(M) = 0 $ for all $i < t$;
\end{enumerate}
where $\widehat{R}$ denotes the $\frak{m}$-adic completion of $R$.

\label{1.2} Let $(R, \frak{m})$ be a  local  ring. Let $M$  be a  finitely generated  $R$-module. Then
\begin{enumerate}
\item[(1)] $\operatorname{CoSupp} (\mathfrak{F}^c_{\frak{a}}( M)) = \operatorname{CoSupp} (\mathfrak{F}^c_{\frak{a}}( R/J))$,
\item[(2)] $\operatorname{Supp} (\mathfrak{F}^c_{\frak{a}}( M)) = \operatorname{Supp} (\mathfrak{F}^c_{\frak{a}}( R/J))$,
\end{enumerate}
where $J$ is $\operatorname{Ann}_{R} M$ and $c:= \dim R/\frak{a}$.

\label{1.3} Let $(R,\frak{m})$ be a local ring of dimension $d > 1$. Let $\mathfrak{F}^{d}_{\frak{a}}(R)=0$. Then:
\begin{enumerate}
\item[(1)] If $\frak{p} \in \operatorname{Coass} \mathfrak{F}^{d-1}_{\frak{a}}(R)$, then it implies that $\dim (R/(\frak{a},\frak{p}))= d-1$.
\item[(2)] $\operatorname{Assh}(R) \cap \operatorname{Coass} \mathfrak{F}^{d-1}_{\frak{a}}(R)\subseteq \{ \frak{p} \in \operatorname{Spec} R: \dim R/\frak{p}=d, \operatorname{Rad} (\frak{a}+ \frak{p}) \neq \frak{m} \}$.
\item[(3)] If  $ \operatorname{Coass} \mathfrak{F}^{d-1}_{\frak{a}}(R)\subseteq \operatorname{Assh}(R)$, then $\{ \frak{p} \in \operatorname{Spec} R: \dim (R/(\frak{a},\frak{p}))= d-1 \} \subseteq \operatorname{Coass} \mathfrak{F}^{d-1}_{\frak{a}}(R)$.
\end{enumerate}

\begin{enumerate}
\item[(1)] Let $\frak{p} \in \operatorname{Cosupp} (M)$, then by definition $D_{R_{\frak{p}}} (D_R(M)_{\frak{p}}) $ is nonzero and so is $D_R(M)_{\frak{p}}$. As  $0 \neq D_R(M)_{\frak{p}}= (D_R(M)_{\frak{q}})_{\frak{p} R_{\frak{q}}}$, then $D_R(M)_{\frak{q}} \neq 0$. It implies that $^{\frak{q}}M \neq 0$.

\item[(2)] Use \cite[2.5]{R} to prove.

\end{enumerate}
$\ \ \ \ \ \ \ \Box

\label{4.1} Let $(R, \frak{m})$ be a  local ring and $M$ an $R$-module. Then the following statements are true:
\begin{enumerate}
\item[(1)] $\operatorname{Coass} (M) \subseteq \operatorname{CoSupp} (M)$.
\item[(2)] Every minimal element of $\operatorname{CoSupp} (M)$ belongs to $\operatorname{Coass} (M)$.
\item[(3)] For any Noetherian $\widehat{R}$-module $M$,   $\operatorname{Coass} (M) = \operatorname{CoSupp} (M) \subseteq \{ \frak{m} \}$, where $\widehat{R}$ denotes the  $\frak{m}$-adic completion of $R$.
\end{enumerate}

\label{4.7} Let $(R,\frak{m})$ be a local ring of dimension $d >1$. Let $\mathfrak{F}^{d}_{\frak{a}}(R)=0$. Then:
\begin{enumerate}
\item[(1)] If $\frak{p} \in \operatorname{Coass} \mathfrak{F}^{d-1}_{\frak{a}}(R)$, then it implies that $\dim (R/(\frak{a},\frak{p}))= d-1$.
\item[(2)] $\operatorname{Assh}(R) \cap \operatorname{Coass} \mathfrak{F}^{d-1}_{\frak{a}}(R)\subseteq \{ \frak{p} \in \operatorname{Spec} R: \dim R/\frak{p}=d, \operatorname{Rad} (\frak{a}+ \frak{p}) \neq \frak{m} \}$.
\item[(3)] If  $ \operatorname{Coass} \mathfrak{F}^{d-1}_{\frak{a}}(R)\subseteq \operatorname{Assh}(R)$, then $\{ \frak{p} \in \operatorname{Spec} R: \dim (R/(\frak{a},\frak{p}))= d-1 \} \subseteq \operatorname{Coass} \mathfrak{F}^{d-1}_{\frak{a}}(R)$.
\end{enumerate}
